use std::collections::{BTreeMap, HashMap};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;

#[derive(Clone, Default)]
struct Counter {
    inner: Arc<Mutex<HashMap<String, u64>>>,
}

impl Counter {
    fn new() -> Self {
        Counter::default()
    }

    fn add(&self, word: &str, n: u64) {
        *self.inner.lock().unwrap().entry(word.to_string()).or_insert(0) += n;
    }

    fn get(&self, word: &str) -> u64 {
        self.inner.lock().unwrap().get(word).copied().unwrap_or(0)
    }

    fn snapshot(&self) -> BTreeMap<String, u64> {
        self.inner.lock().unwrap().iter().map(|(k, v)| (k.clone(), *v)).collect()
    }
}

fn count_words(lines: &[&str], threads: usize) -> BTreeMap<String, u64> {
    assert!(threads > 0);
    let counter = Counter::new();
    let size = lines.len().div_ceil(threads).max(1);
    thread::scope(|s| {
        for part in lines.chunks(size) {
            let counter = counter.clone();
            s.spawn(move || {
                let mut local: HashMap<String, u64> = HashMap::new();
                for line in part {
                    for w in line.to_lowercase().split(|c: char| !c.is_alphabetic()).filter(|w| !w.is_empty()) {
                        *local.entry(w.to_string()).or_insert(0) += 1;
                    }
                }
                for (w, n) in local {
                    counter.add(&w, n);
                }
            });
        }
    });
    counter.snapshot()
}

struct Hits {
    total: AtomicU64,
}

impl Hits {
    fn new() -> Self {
        Hits { total: AtomicU64::new(0) }
    }

    fn hit(&self) {
        self.total.fetch_add(1, Ordering::Relaxed);
    }

    fn get(&self) -> u64 {
        self.total.load(Ordering::Relaxed)
    }
}

unitTests:
test("a shared counter", || {
    let a = Counter::new();
    let b = a.clone();
    a.add("tea", 2);
    b.add("tea", 3);
    b.add("cake", 1);
    check_eq(a.get("tea"), 5);
    check_eq(a.get("mug"), 0);
    check_eq(a.snapshot().into_iter().collect::<Vec<_>>(), vec![("cake".to_string(), 1), ("tea".to_string(), 5)]);
});

test("counting from many threads at once", || {
    let c = Counter::new();
    std::thread::scope(|s| {
        for _ in 0..8 {
            let c = c.clone();
            s.spawn(move || { for _ in 0..1000 { c.add("x", 1); } });
        }
    });
    check_eq(c.get("x"), 8000);
});

test("parallel word count", || {
    let lines = ["The cat sat", "the CAT ran!", "a dog; the end", "", "cat"];
    let counts = count_words(&lines, 3);
    check_eq(counts.get("the").copied(), Some(3));
    check_eq(counts.get("cat").copied(), Some(3));
    check_eq(counts.len(), 7);
    check_eq(count_words(&lines, 1), counts);
    check_eq(count_words(&[], 4).len(), 0);
});

test("lock-free hits", || {
    let hits = Hits::new();
    std::thread::scope(|s| {
        for _ in 0..4 {
            s.spawn(|| { for _ in 0..2500 { hits.hit(); } });
        }
    });
    check_eq(hits.get(), 10_000);
});

